    if keys == {"sources", "quorum"}:
        return "policy"
    if keys == {"source", "report", "state"}:
        return "vote"
    return None

def _chain_arbitration_policies(
    self, wallet_id: str
) -> dict[str, dict]:
    """从审计事件序列恢复各资产的多源仲裁策略（按 seq 升序重放，
    每资产取最后一条）。

    新策略只写 chain_vote 事件（details 键集 {sources,quorum}）；
